function [s0, l1] = fmr_loop(face, perim)
%FMR_LOOP  The loop a ring of face [m^2] and perimeter [m] encloses: 80 % of each.
%   face: real[1] (passed a plain number)
%   perim: real[1] (passed a plain number)
%   returns s0: real[1] (passed a plain number)
%   returns l1: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s0 = 0;
    l1 = 0;
    s0 = (0.8 * face);
    l1 = (0.8 * perim);
end
